head.b:skin:
:root{--bg:#f7f2e9;--paper:#fffdf9;--ink:#1f1e1b;--muted:#736e66;--line:#ddd5c8;--accent:#c95545;--sage:#a8b5a1;--blue:#8ea4b9;--gold:#dfb763;--radius:18px;--shadow:0 12px 30px rgba(31,30,27,.07)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,Helvetica,sans-serif;line-height:1.65}a{color:inherit;text-decoration:none}img{display:block;max-width:100%;height:auto}.wrap{width:min(1180px,92vw);margin:0 auto}
.topline{border-top:3px solid var(--ink);border-bottom:1px solid var(--line);padding:9px 0;color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.11em;text-transform:uppercase}
.masthead{padding:28px 0 22px;display:flex;align-items:center;justify-content:space-between;gap:22px}.brand{font-size:40px;font-weight:900;letter-spacing:-.06em;line-height:.95}.brand-sub{margin-top:8px;color:var(--muted);font-size:10px;font-weight:700;letter-spacing:.2em;text-transform:uppercase}.search-link{border:1px solid #c9c0b3;background:var(--paper);border-radius:10px;padding:10px 15px;font-size:13px;font-weight:700}
.nav-area{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:#fbf7f0}.nav-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;padding:12px 0}.nav-item{display:flex;align-items:center;gap:8px;min-height:42px;background:var(--paper);border:1px solid #d9d1c5;border-radius:10px;padding:8px 10px;font-size:12px;font-weight:700}.nav-item:hover{border-color:var(--accent);transform:translateY(-1px)}.nav-icon{width:24px;height:24px;display:grid;place-items:center;border-radius:7px;background:#efe8de;font-size:10px;font-weight:800;flex:0 0 24px}
.hero{padding:30px 0 25px;display:grid;grid-template-columns:1.55fr .65fr;gap:20px}.hero-main{position:relative;min-height:465px;border-radius:var(--radius);overflow:hidden;background:#dcd4c7}.hero-main img{width:100%;height:100%;object-fit:cover}.hero-overlay{position:absolute;left:0;right:0;bottom:0;padding:46px 40px 34px;color:#fff;background:linear-gradient(180deg,transparent,rgba(0,0,0,.8))}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.hero h1{margin:8px 0 10px;font-family:Georgia,'Times New Roman',serif;font-size:clamp(44px,5.6vw,76px);line-height:.95;letter-spacing:-.045em;max-width:780px}.hero p{margin:0;font-size:17px;max-width:680px}.side-stack{display:grid;gap:20px}.side-card{display:flex;flex-direction:column;justify-content:flex-end;min-height:222px;background:var(--paper);border:1px solid #e1d9ce;border-radius:var(--radius);padding:27px;box-shadow:var(--shadow)}.side-card .label{width:max-content;padding:6px 9px;border-radius:7px;background:var(--sage);font-size:10px;font-weight:800;letter-spacing:.11em;text-transform:uppercase}.side-card h2{margin:10px 0 8px;font-family:Georgia,'Times New Roman',serif;font-size:28px;line-height:1.04}.side-card p{margin:0;color:var(--muted);font-size:13px}
.section{padding:28px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:15px;margin-bottom:16px}.section-head h2{margin:0;font-family:Georgia,'Times New Roman',serif;font-size:36px;line-height:1.02;letter-spacing:-.04em}.section-head a{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.topic-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.topic{background:var(--paper);border:1px solid #e0d8cd;border-radius:14px;padding:19px;min-height:145px;display:flex;flex-direction:column;justify-content:space-between}.topic:hover{border-color:var(--accent);box-shadow:var(--shadow)}.topic-num{font-size:10px;color:var(--muted);font-weight:800;letter-spacing:.14em}.topic-name{font-family:Georgia,'Times New Roman',serif;font-size:22px;line-height:1.06}
.reset-band{margin:28px 0 8px;padding:30px 34px;background:var(--ink);color:#fff;border-radius:var(--radius);display:flex;align-items:center;justify-content:space-between;gap:25px}.reset-band h2{margin:0 0 7px;font-family:Georgia,'Times New Roman',serif;font-size:34px;line-height:1.05}.reset-band p{margin:0;color:#d1ccc4}.reset-band a{background:#fff;color:var(--ink);border-radius:10px;padding:11px 15px;font-size:11px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;white-space:nowrap}
.main-area{padding:45px 0;display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:38px}.sidebar-box{background:var(--paper);border:1px solid #e0d8cd;border-radius:14px;padding:20px;margin-bottom:14px}.sidebar-box h3{margin:0 0 10px;font-size:11px;letter-spacing:.12em;text-transform:uppercase}.sidebar-box ul{list-style:none;padding:0;margin:0}.sidebar-box li{padding:8px 0;border-bottom:1px solid var(--line);font-size:13px}.blog-posts{font-size:17px}.blog-posts h2,.blog-posts h3{font-family:Georgia,'Times New Roman',serif}.blog-posts h2{font-size:34px}
.footer{margin-top:55px;background:#1d1c19;color:#f3efe7;padding:50px 0}.footer-grid{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:35px}.footer h3{margin:0 0 10px;font-family:Georgia,'Times New Roman',serif;font-size:32px}.footer p,.footer a{color:#bab4aa;font-size:13px}.footer-links{display:grid;gap:7px}.copy{margin-top:30px;padding-top:18px;border-top:1px solid #34322d;color:#89837a;font-size:11px}
@media(max-width:980px){.nav-grid{grid-template-columns:repeat(3,1fr)}.hero{grid-template-columns:1fr}.topic-grid{grid-template-columns:repeat(2,1fr)}.main-area{grid-template-columns:1fr}.footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.topline{font-size:9px}.masthead{padding:22px 0 18px}.brand{font-size:31px}.brand-sub{font-size:8px;letter-spacing:.15em}.search-link{display:none}.nav-grid{grid-template-columns:repeat(2,1fr);gap:7px}.nav-item{font-size:11px}.hero{padding-top:20px}.hero-main{min-height:390px}.hero-overlay{padding:30px 22px 24px}.hero h1{font-size:43px}.hero p{font-size:14px}.side-card h2{font-size:26px}.topic-grid{grid-template-columns:1fr 1fr}.topic{min-height:130px;padding:16px}.topic-name{font-size:19px}.reset-band{display:block;padding:27px}.reset-band a{display:inline-block;margin-top:16px}.footer-grid{grid-template-columns:1fr}.main-area{padding:34px 0}}
